package main

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strings"
)

const (
	maxKeyLength = 64
	maxValueSize = 1 << 20 // 1 MiB
	kvPrefix     = "/kv/"
)

// Handler routes requests to the key-value API backed by a Store.
type Handler struct {
	store *Store
}

// NewHandler returns an http.Handler serving the API for store.
func NewHandler(store *Store) *Handler {
	return &Handler{store: store}
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// Use the escaped path so percent-encoded characters are never mistaken
	// for valid key characters.
	path := r.URL.EscapedPath()
	switch {
	case path == "/health":
		h.health(w, r)
	case path == "/kv":
		h.list(w, r)
	case strings.HasPrefix(path, kvPrefix):
		h.key(w, r, strings.TrimPrefix(path, kvPrefix))
	default:
		writeText(w, http.StatusNotFound, "not found")
	}
}

func (h *Handler) health(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		methodNotAllowed(w, "GET")
		return
	}
	writeText(w, http.StatusOK, "ok")
}

func (h *Handler) list(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		methodNotAllowed(w, "GET")
		return
	}
	body, err := json.Marshal(h.store.Keys())
	if err != nil {
		log.Printf("encode keys: %v", err)
		writeText(w, http.StatusInternalServerError, "internal server error")
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write(body)
}

func (h *Handler) key(w http.ResponseWriter, r *http.Request, key string) {
	if !validKey(key) {
		writeText(w, http.StatusBadRequest, "invalid key")
		return
	}
	switch r.Method {
	case http.MethodGet:
		value, ok := h.store.Get(key)
		if !ok {
			writeText(w, http.StatusNotFound, "not found")
			return
		}
		w.Header().Set("Content-Type", "application/octet-stream")
		w.WriteHeader(http.StatusOK)
		w.Write(value)
	case http.MethodPut:
		value, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxValueSize))
		if err != nil {
			if maxErr := (*http.MaxBytesError)(nil); errors.As(err, &maxErr) {
				writeText(w, http.StatusRequestEntityTooLarge, "value too large")
			} else {
				writeText(w, http.StatusBadRequest, "bad request body")
			}
			return
		}
		if h.store.Put(key, value) {
			w.WriteHeader(http.StatusCreated)
		} else {
			w.WriteHeader(http.StatusOK)
		}
	case http.MethodDelete:
		if !h.store.Delete(key) {
			writeText(w, http.StatusNotFound, "not found")
			return
		}
		w.WriteHeader(http.StatusNoContent)
	default:
		methodNotAllowed(w, "GET, PUT, DELETE")
	}
}

// validKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func validKey(key string) bool {
	if len(key) == 0 || len(key) > maxKeyLength {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

func methodNotAllowed(w http.ResponseWriter, allow string) {
	w.Header().Set("Allow", allow)
	writeText(w, http.StatusMethodNotAllowed, "method not allowed")
}

func writeText(w http.ResponseWriter, status int, body string) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.WriteHeader(status)
	io.WriteString(w, body)
}

package main

import (
	"bytes"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
)

func do(t *testing.T, srv *httptest.Server, method, path string, body []byte) (int, http.Header, []byte) {
	t.Helper()
	var rd io.Reader
	if body != nil {
		rd = bytes.NewReader(body)
	}
	req, err := http.NewRequest(method, srv.URL+path, rd)
	if err != nil {
		t.Fatal(err)
	}
	resp, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatal(err)
	}
	return resp.StatusCode, resp.Header, b
}

func TestRoutes(t *testing.T) {
	srv := httptest.NewServer(NewHandler(NewStore()))
	defer srv.Close()

	big := bytes.Repeat([]byte{0xff, 0x00, 'x'}, maxValueSize/3+1)[:maxValueSize]
	tests := []struct {
		method, path string
		body         []byte
		status       int
		want         string
	}{
		{"GET", "/health", nil, 200, "ok"},
		{"POST", "/health", nil, 405, ""},
		{"GET", "/kv", nil, 200, "[]"},
		{"PUT", "/kv/b", []byte("2"), 201, ""},
		{"PUT", "/kv/A-_9", []byte("1"), 201, ""},
		{"PUT", "/kv/b", []byte("3"), 200, ""},
		{"GET", "/kv/b", nil, 200, "3"},
		{"GET", "/kv", nil, 200, `["A-_9","b"]`},
		{"PUT", "/kv/big", big, 201, ""},
		{"GET", "/kv/big", nil, 200, string(big)},
		{"PUT", "/kv/huge", append(big, 1), 413, ""},
		{"PUT", "/kv/empty", []byte{}, 201, ""},
		{"GET", "/kv/empty", nil, 200, ""},
		{"DELETE", "/kv/b", nil, 204, ""},
		{"DELETE", "/kv/b", nil, 404, ""},
		{"GET", "/kv/b", nil, 404, ""},
		{"PATCH", "/kv/a", nil, 405, ""},
		{"POST", "/kv", nil, 405, ""},
		{"GET", "/kv/", nil, 400, ""},
		{"GET", "/kv/a/b", nil, 400, ""},
		{"GET", "/kv/bad.key", nil, 400, ""},
		{"GET", "/kv/%41", nil, 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 64), nil, 404, ""},
		{"GET", "/kv/" + strings.Repeat("k", 65), nil, 400, ""},
		{"GET", "/nope", nil, 404, ""},
		{"GET", "/", nil, 404, ""},
		{"GET", "/kvx", nil, 404, ""},
	}
	for _, tt := range tests {
		status, hdr, body := do(t, srv, tt.method, tt.path, tt.body)
		if status != tt.status {
			t.Errorf("%s %s: status %d, want %d", tt.method, tt.path, status, tt.status)
			continue
		}
		if tt.want != "" && string(body) != tt.want {
			t.Errorf("%s %s: body %.40q, want %.40q", tt.method, tt.path, body, tt.want)
		}
		if tt.path == "/kv" && status == 200 && hdr.Get("Content-Type") != "application/json" {
			t.Errorf("GET /kv: content-type %q", hdr.Get("Content-Type"))
		}
	}
}

func TestConcurrentPuts(t *testing.T) {
	store := NewStore()
	srv := httptest.NewServer(NewHandler(store))
	defer srv.Close()

	var wg sync.WaitGroup
	for i := range 64 {
		wg.Go(func() {
			key := "k" + strings.Repeat("x", i%10) + string(rune('a'+i%26))
			req, _ := http.NewRequest("PUT", srv.URL+"/kv/"+key, strings.NewReader(key))
			resp, err := srv.Client().Do(req)
			if err != nil {
				t.Error(err)
				return
			}
			resp.Body.Close()
		})
	}
	wg.Wait()
	if n := len(store.Keys()); n == 0 {
		t.Fatal("no keys stored")
	}
}

// Command app is an HTTP/1.1 in-memory key-value server.
//
// Usage:
//
//	app <port>
//
// It listens on 127.0.0.1:<port> and serves until killed.
package main

import (
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"strconv"
	"time"
)

const (
	maxHeaderBytes = 64 << 10
	ioTimeout      = 10 * time.Second
)

func main() {
	log.SetFlags(0)
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: %s <port>\n", os.Args[0])
		os.Exit(2)
	}
	port, err := strconv.ParseUint(os.Args[1], 10, 16)
	if err != nil || port == 0 {
		fmt.Fprintf(os.Stderr, "invalid port: %s\n", os.Args[1])
		os.Exit(2)
	}

	srv := &http.Server{
		Addr:              net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10)),
		Handler:           NewHandler(NewStore()),
		ReadHeaderTimeout: ioTimeout,
		ReadTimeout:       ioTimeout,
		WriteTimeout:      ioTimeout,
		IdleTimeout:       ioTimeout,
		MaxHeaderBytes:    maxHeaderBytes,
	}
	if err := srv.ListenAndServe(); err != nil {
		log.Fatalf("fatal: %v", err)
	}
}

package main

import (
	"maps"
	"slices"
	"sync"
)

// Store is a concurrency-safe in-memory key-value store.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// NewStore returns an empty Store.
func NewStore() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Put stores value under key and reports whether the key was newly created.
// The store takes ownership of value.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.data[key]
	s.data[key] = value
	return !exists
}

// Get returns the value stored under key. The returned slice must not be
// modified.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.data[key]; !ok {
		return false
	}
	delete(s.data, key)
	return true
}

// Keys returns every key in ascending order. The result is never nil.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := slices.AppendSeq(make([]string, 0, len(s.data)), maps.Keys(s.data))
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}
